import { lazy } from 'react'
import type { ComponentType, LazyExoticComponent } from 'react'
import { MembersOnly } from '../components/MembersOnly'

/**
 * Each page is its own chunk, fetched on first navigation to its route.
 * Workbox precaches the public chunks, so they are still available offline.
 */
function lazyPage<M extends Record<string, unknown>>(load: () => Promise<M>, name: keyof M) {
  return lazy(async () => ({ default: (await load())[name] as ComponentType }))
}

/**
 * A page for signed-in members only: studies, 3D anatomy and protocols (the author's decision,
 * 2026-10-28). vite.config.ts builds every `membersPage` import into `/members/assets/`, which
 * Cloudflare Access guards, so without a session the chunk fails to load and the page asks the
 * reader to sign in. Calculators and classifications stay public (`lazyPage`).
 */
function membersPage<M extends Record<string, unknown>>(load: () => Promise<M>, name: keyof M) {
  return lazy(async () => {
    try {
      return { default: (await load())[name] as ComponentType }
    } catch {
      return { default: MembersOnly }
    }
  })
}

/**
 * Body regions are the main way in (the author's decision, 2026-10-28): the home page, the menu
 * and `/regions/:slug` list everything for one area together, and the kind of page is a label.
 * General holds what belongs to no one region: contrast safety, IR anticoagulation and formulas.
 */
export const regions = [
  'Neuro', 'Head and neck', 'Chest', 'Abdomen', 'Pelvis', 'Spine', 'Shoulder', 'Elbow', 'Wrist and hand', 'Hip', 'Knee', 'Ankle and foot', 'General',
] as const

export type Region = (typeof regions)[number]

/** What a page is, in the order a region page lists them. */
export const kinds = ['study', 'classification', 'calculator', 'anatomy', 'protocol'] as const

export type Kind = (typeof kinds)[number]

const kindLabels: Record<Kind, [one: string, many: string]> = {
  study: ['Study', 'Studies'],
  classification: ['Classification', 'Classifications'],
  calculator: ['Calculator', 'Calculators'],
  anatomy: ['3D anatomy', '3D anatomy'],
  protocol: ['Protocol', 'Protocols'],
}

/** 'Study' for one page of a kind, 'Studies' for a heading over several. */
export function kindLabel(kind: Kind, plural = false) {
  return kindLabels[kind][plural ? 1 : 0]
}

export type CalculatorItem = {
  path: string
  name: string
  description: string
  region: Region
  /** Other regions that list this page too, e.g. the pelvis CT study under Hip. */
  alsoIn?: Region[]
  kind: Kind
  /** Extra search terms: synonyms, organs, acronyms, and criteria names. */
  keywords?: string[]
  /** The page rendered at `path`. Listing it here is what registers the route. */
  component: LazyExoticComponent<ComponentType>
  /**
   * Paths of closely related items, e.g. a lesson and the calculator that applies it.
   * Declare a link on one side only; `relatedTo` makes it two-way.
   */
  related?: string[]
  /** Short mono label shown on the home row; only a version or source the page itself states. */
  tag?: string
}

export type IndexedCalculator = CalculatorItem

