const byPath = new Map(calculators.map((item) => [item.path, item]))

/** Items linked to `path` from either side, in registry order. */
export function relatedTo(path: string): IndexedCalculator[] {
  const own = byPath.get(path)?.related ?? []
  return calculators.filter(
    (item) => item.path !== path && (own.includes(item.path) || (item.related ?? []).includes(path)),
  )
}

/** 'wrist-and-hand' for 'Wrist and hand'. */
export function regionSlug(region: Region) {
  return region.toLowerCase().replace(/[^a-z0-9]+/g, '-')
}

export function regionPath(region: Region) {
  return `/regions/${regionSlug(region)}`
}

export function regionForSlug(slug: string | undefined): Region | undefined {
  return regions.find((region) => regionSlug(region) === slug)
}

/** The pages listed under `region`, its own and those it shares, grouped by kind in `kinds` order. */
export function regionGroups(region: Region): { kind: Kind; items: IndexedCalculator[] }[] {
  const items = calculators.filter((item) => item.region === region || (item.alsoIn ?? []).includes(region))
  return kinds
    .map((kind) => ({ kind, items: items.filter((item) => item.kind === kind) }))
    .filter((group) => group.items.length > 0)
}

/** "1 study, 4 classifications, 3D anatomy": what a region holds, for its row on the home page. */
export function regionSummary(region: Region) {
  return regionGroups(region)
    .map(({ kind, items }) => (kind === 'anatomy' ? kindLabel(kind) : `${items.length} ${kindLabel(kind, items.length > 1).toLowerCase()}`))
    .join(', ')
}

/** Every entered word must appear somewhere in the item, so extra words narrow the list. */
export function matchesQuery(item: IndexedCalculator, query: string) {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean)
  if (words.length === 0) return true
  const haystack = [item.name, item.description, item.region, ...(item.alsoIn ?? []), kindLabel(item.kind), kindLabel(item.kind, true), ...(item.keywords ?? [])]
    .join(' ')
    .toLowerCase()
  return words.every((word) => haystack.includes(word))
}

/**
 * Pages that moved: the old path redirects to the new one so links and installed bookmarks keep
 * working. The calvarial lesions and hearing loss references are teaching pages, so they moved
 * to `/studies/` (2026-10-28).
 */
export const movedPaths: Record<string, string> = {
  '/calvarium': '/studies/calvarium',
  '/hearing-loss-ct': '/studies/hearing-loss-ct',
}
